css:
:root {
  --radius: 0px;
  --radius-xs: 0px;
  --radius-sm: 0px;
  --radius-md: 0px;
  --radius-lg: 0px;
  --radius-xl: 0px;
  --radius-2xl: 0px;
  --control-radius: 0px;
  --font-sans: var(--font-mono);
  --font-composer: var(--font-mono);
  --mb-comment: #8a8a8d;
  --mb-foreground: #eaeaea;
  --mb-string: #eaeaea;
  --mb-keyword: #059669;
  --mb-function: #f87171;
  --mb-type: #fbbf24;
  --mb-number: #efbf04;
  --mb-constant: #d97706;
  --mb-variable: #d97706;
  --mb-builtin: #f59e0b;
  --mb-special: #f59e0b;
  --mb-regex: #efbf04;
  --mb-operator: #bebebe;
  --mb-punctuation: #8a8a8d;
  --mb-property: #3b82f6;
  --mb-class: #fbbf24;
  --mb-tag: #059669;
  --mb-decorator: #3b82f6;
  --mb-parameter: #bebebe;
  --mb-added: #10b981;
  --mb-deleted: #f87171;
  --mb-modified: #f59e0b;
}

[data-app-sidebar],
[data-slot="sidebar-inner"] {
  background: #121212 !important;
  background-image: none !important;
}

[data-app-sidebar] {
  border-right: 2px solid rgb(255 255 255 / 30%) !important;
}

[data-slot="sidebar-inner"] {
  border-right: 0 !important;
}

[data-preview-panel-mode="inline"] {
  border-left: 1px solid rgb(255 255 255 / 24%) !important;
}

:root,
html[data-theme-id] {
  --code-background: #121212 !important;
}

[data-thread-details-card],
[data-thread-details-panel] {
  border-radius: 0 !important;
}

[data-right-panel-tabbar] {
  border-bottom: 2px solid rgb(255 255 255 / 30%) !important;
}


[data-thread-details-card] [role="group"],
[data-thread-details-panel] [role="group"],
[data-surface-subheader] [role="group"],
[data-file-browser-panel] [role="group"],
[data-right-panel-tabbar] [role="group"] {
  border-radius: 0 !important;
}

[data-preview-panel-mode],
[data-right-panel-tabbar],
[data-right-panel-surface-content],
[data-right-panel-surface-content] > div,
[data-file-browser-panel],
[data-file-browser-panel] [data-slot="scroll-area-viewport"],
[aria-label="File explorer"] {
  border-left: 1px solid rgb(255 255 255 / 24%) !important;
}

[aria-label="File explorer"],
[data-surface-subheader],
[data-preview-panel-mode] [data-surface-subheader] {
  background-color: #121212 !important;
  border-bottom: 2px solid rgb(255 255 255 / 30%) !important;
}

[data-preview-panel-mode] [data-surface-subheader] {
  height: 40px !important;
  min-height: 40px !important;
  padding-top: 4px !important;
  padding-bottom: 4px !important;
}

[data-app-sidebar] [data-sidebar-row],
[data-app-sidebar] [data-thread-item] {
  border-radius: 0;
}

[data-app-sidebar] a[aria-label="T3 Code home"] {
  display: none !important;
}

[data-sidebar-control] [data-slot="sidebar-trigger"],
[data-app-sidebar] [data-slot="sidebar-trigger"],
[data-app-sidebar] [aria-label="Go back"],
[data-app-sidebar] [aria-label="Go forward"] {
  width: 26px !important;
  height: 26px !important;
  min-width: 26px !important;
  padding: 0 !important;
  border: 1px solid transparent !important;
  border-radius: 5px !important;
  background: transparent !important;
  box-shadow: none !important;
  color: #8a8a8d !important;
}

[data-sidebar-control] [data-slot="sidebar-trigger"]:hover,
[data-app-sidebar] [data-slot="sidebar-trigger"]:hover,
[data-app-sidebar] [aria-label="Go back"]:hover,
[data-app-sidebar] [aria-label="Go forward"]:hover {
  color: #eaeaea !important;
  border-color: #2a2a2a !important;
  background: #1a1a1a !important;
}

[data-sidebar-control] [data-slot="sidebar-trigger"][aria-pressed="true"] {
  color: var(--app-theme-accent) !important;
}

[data-sidebar-control] [data-slot="sidebar-trigger"]:focus-visible,
[data-app-sidebar] [data-slot="sidebar-trigger"]:focus-visible,
[data-app-sidebar] [aria-label="Go back"]:focus-visible,
[data-app-sidebar] [aria-label="Go forward"]:focus-visible {
  outline: 1px solid var(--app-theme-accent) !important;
  outline-offset: 2px;
  box-shadow: none !important;
}

[data-app-sidebar] [aria-label="Go back"] {
  margin-left: 2.75rem;
}

[data-app-sidebar] [aria-label="Go forward"] {
  margin-left: 2px;
}

[data-app-sidebar] [data-sidebar-row][aria-current="page"] {
  background: transparent !important;
  color: var(--app-theme-accent) !important;
  box-shadow: inset 2px 0 0 var(--app-theme-accent);
}

[data-chat-header] {
  background: #121212 !important;
  border-bottom: 2px solid rgb(255 255 255 / 30%) !important;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 10px;
}

[data-workspace-area="conversation"] {
  background-color: #121212 !important;
  background-image: none !important;
}


[data-user-message-bubble] {
  border-radius: 0 !important;
  border: 1px solid #262626 !important;
  border-left: 2px solid var(--app-theme-accent) !important;
  background: #171717 !important;
}

.chat-markdown-codeblock {
  border-radius: 0 !important;
  border: 1px solid #262626 !important;
  border-left: 2px solid #333333 !important;
  background: #090909 !important;
}

[data-chat-composer-form] [data-slot="composer-host"],
[data-slot="composer-host"] {
  border-radius: 0 !important;
  border: 2px solid rgb(255 255 255 / 38%) !important;
  background: #111111 !important;
}

[data-chat-composer-form]:focus-within [data-slot="composer-host"] {
  border-color: var(--app-theme-accent) !important;
  box-shadow: inset 2px 0 0 var(--app-theme-accent) !important;
}

[data-slot="dialog-popup"],
[data-slot="menu-popup"],
[data-slot="popover-popup"] {
  border-radius: 0 !important;
  border: 1px solid rgb(255 255 255 / 30%) !important;
  background: #0d0d0d !important;
  box-shadow: 0 0 0 1px #000, 0 34px 90px rgb(0 0 0 / 78%) !important;
}

[data-slot="separator"],
[role="separator"][aria-orientation="horizontal"] {
  background-color: rgb(255 255 255 / 24%) !important;
}


[data-right-panel-tabbar] [data-active-tab] {
  border: 1px solid rgb(255 255 255 / 24%) !important;
  border-radius: 0 !important;
  background: #171717 !important;
}

[data-slot="input"] {
  border-radius: 0 !important;
  border: 1px solid rgb(255 255 255 / 24%) !important;
  background: #111111 !important;
  color: #eaeaea !important;
  box-shadow: none !important;
}

[data-slot="input"]::placeholder {
  color: #8a8a8d !important;
}

[data-slot="input"]:focus-visible {
  outline: none !important;
  border-color: var(--app-theme-accent) !important;
  box-shadow: inset 0 0 0 1px var(--app-theme-accent) !important;
}

[data-slot="input-group"] {
  border: 1px solid rgb(255 255 255 / 24%) !important;
  border-radius: 0 !important;
  background: #111111 !important;
  box-shadow: none !important;
}

[data-slot="input-group"]::before {
  display: none !important;
}

[data-slot="input-group"]:focus-within {
  border-color: var(--app-theme-accent) !important;
  box-shadow: inset 0 0 0 1px var(--app-theme-accent) !important;
}

[data-slot="input-group"] [data-slot="input"] {
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

[data-slot="input-group-addon"] {
  color: #8a8a8d !important;
}

/* O search da sidebar é um input "unstyled" dentro de uma linha com ícone.
   A caixa vai no container, para o ícone e o texto respirarem juntos. */
/* Sidebar de threads e menu de Settings usam a mesma linha de busca. */
:is([data-app-sidebar], [role="navigation"]) div:has(> :is([data-slot="input"], [data-slot="input-control"])) {
  height: 32px !important;
  padding: 0 8px !important;
  gap: 8px !important;
  border: 1px solid rgb(255 255 255 / 24%) !important;
  border-radius: 0 !important;
  background: #111111 !important;
  box-shadow: none !important;
}

:is([data-app-sidebar], [role="navigation"]) div:has(> :is([data-slot="input"], [data-slot="input-control"])):focus-within {
  border-color: var(--app-theme-accent) !important;
  box-shadow: inset 0 0 0 1px var(--app-theme-accent) !important;
}

:is([data-app-sidebar], [role="navigation"]) [data-slot="input-control"] {
  display: flex !important;
  align-items: center !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  height: 100% !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

:is([data-app-sidebar], [role="navigation"]) [data-slot="input-control"]::before {
  display: none !important;
}

:is([data-app-sidebar], [role="navigation"]) [data-slot="input"],
:is([data-app-sidebar], [role="navigation"]) [data-slot="input-control"] [data-slot="input"] {
  height: 100% !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 0 !important;
  line-height: normal !important;
}

:is([data-app-sidebar], [role="navigation"]) [data-slot="input"]:focus-visible,
:is([data-app-sidebar], [role="navigation"]) [data-slot="input-control"] [data-slot="input"]:focus-visible {
  outline: none !important;
  border: 0 !important;
  box-shadow: none !important;
}

[data-slot="select-trigger"],
[data-slot="textarea"] {
  border: 1px solid rgb(255 255 255 / 24%) !important;
  border-radius: 0 !important;
  background: #111111 !important;
  color: #eaeaea !important;
  box-shadow: none !important;
}

[data-slot="select-trigger"]:focus-visible,
[data-slot="textarea"]:focus-visible {
  outline: none !important;
  border-color: var(--app-theme-accent) !important;
  box-shadow: inset 0 0 0 1px var(--app-theme-accent) !important;
}

[data-slot="menu-popup"] [aria-selected="true"],
[data-slot="dialog-popup"] [aria-selected="true"],
[data-slot="dialog-popup"] [data-highlighted],
[data-slot="menu-popup"] [data-highlighted] {
  background: #212121 !important;
  box-shadow: inset 2px 0 0 var(--app-theme-accent);
}

/* Syntax highlighting: o T3 Code usa o tema fixo "pierre-dark" nos code
   blocks. Remapeamos as cores inline do Shiki para a paleta do matteblack.nvim. */
.chat-markdown-codeblock pre,
.chat-markdown-codeblock code {
  color: var(--mb-foreground) !important;
  background: transparent !important;
}

.chat-markdown-codeblock span[style*="#737373" i] {
  color: var(--mb-comment) !important;
  font-style: italic;
}

.chat-markdown-codeblock span[style*="#636363" i] {
  color: var(--mb-punctuation) !important;
}

.chat-markdown-codeblock span[style*="#5ecc71" i] {
  color: var(--mb-string) !important;
}

.chat-markdown-codeblock span[style*="#61d5c0" i] {
  color: var(--mb-special) !important;
}

.chat-markdown-codeblock span[style*="#64d1db" i] {
  color: var(--mb-regex) !important;
}

.chat-markdown-codeblock span[style*="#68cdf2" i] {
  color: var(--mb-number) !important;
}

.chat-markdown-codeblock span[style*="#ffd452" i] {
  color: var(--mb-constant) !important;
}

.chat-markdown-codeblock span[style*="#ff678d" i] {
  color: var(--mb-keyword) !important;
}

.chat-markdown-codeblock span[style*="#08c0ef" i] {
  color: var(--mb-operator) !important;
}

.chat-markdown-codeblock span[style*="#9d6afb" i] {
  color: var(--mb-function) !important;
}

.chat-markdown-codeblock span[style*="#d568ea" i] {
  color: var(--mb-type) !important;
}

.chat-markdown-codeblock span[style*="#ffa359" i] {
  color: var(--mb-variable) !important;
}

.chat-markdown-codeblock span[style*="#ffab16" i] {
  color: var(--mb-builtin) !important;
}

.chat-markdown-codeblock span[style*="#009fff" i] {
  color: var(--mb-property) !important;
}

.chat-markdown-codeblock span[style*="#60d199" i] {
  color: var(--mb-class) !important;
}

.chat-markdown-codeblock span[style*="#ff855e" i] {
  color: var(--mb-tag) !important;
}

.chat-markdown-codeblock span[style*="#69b1ff" i] {
  color: var(--mb-decorator) !important;
}

.chat-markdown-codeblock span[style*="#a3a3a3" i] {
  color: var(--mb-parameter) !important;
}

.chat-markdown-codeblock span[style*="#fafafa" i] {
  color: var(--mb-foreground) !important;
}

.chat-markdown-codeblock span[style*="#07c480" i] {
  color: var(--mb-added) !important;
}

.chat-markdown-codeblock span[style*="#ff2e3f" i] {
  color: var(--mb-deleted) !important;
}

.chat-markdown-codeblock span[style*="#ffca00" i] {
  color: var(--mb-modified) !important;
}

button,
[role="menuitem"],
[data-slot="button"],
[data-slot="toggle"],
[data-slot="menu-trigger"],
[data-slot="select-trigger"] {
  border-radius: 0 !important;
}
